function shrinkToMinimal(items, stillFails) {
  // TODO: repeatedly try removing one item at a time; whenever a removal
  // still fails, keep the smaller array and try again from there.
  // Stop and return when no single removal still fails.
}

items.solution:
function shrinkToMinimal(items, stillFails) {
  let current = items;
  let didShrink = true;
  while (didShrink) {
    didShrink = false;
    for (let i = 0; i < current.length; i++) {
      const smaller = current.filter((_, idx) => idx !== i);
      if (stillFails(smaller)) {
        current = smaller;
        didShrink = true;
        break;
      }
    }
  }
  return current;
}
